def has_cycle(head):
    slow = fast = head
    while fast.next and fast:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

def remove_nth_from_end(head, n):
    slow = fast = head
    for _ in range(n):
        fast = fast.next
    while fast.next:
        slow = slow.next
        fast = fast.next
    slow.next = slow.next.next
    return head
